import{_ as t,o,c as r,a7 as s}from"./chunks/framework.C4ZIv4ii.js";const a="/falconcms/screenshots/wholesale-apply.webp",n="/falconcms/screenshots/wholesale-customers.webp",i="/falconcms/screenshots/wholesale-customer.webp",l="/falconcms/screenshots/wholesale-level.webp",w=JSON.parse('{"title":"Customers & Levels","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/customers.md","filePath":"wholesale/customers.md","lastUpdated":1792170474000}'),h={name:"wholesale/customers.md"};function d(c,e,p,m,u,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="customers-levels" tabindex="-1">Customers &amp; Levels <a class="header-anchor" href="#customers-levels" aria-label="Permalink to &quot;Customers &amp; Levels&quot;">​</a></h1><p>A wholesale customer is an ordinary customer account with a <strong>wholesale account</strong> attached: their company details, a status (pending, approved or rejected) and a <strong>level</strong>. Only approved accounts get wholesale prices and rules.</p><hr><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h2><p>Businesses apply in one of three places:</p><ul><li>the application page, <strong><code>/wholesale/apply</code></strong>;</li><li><strong>My Account → Wholesale</strong>, for a customer who already has an account;</li><li>any page with the <strong><code>[falcon_wholesale_apply]</code></strong> shortcode, which shows a link to the form.</li></ul><p><img src="'+a+'" alt="The wholesale application form"></p><p><em>The application form, as a visitor without an account sees it.</em></p><p>The form asks for:</p><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td>Your name, email, password</td><td>Only for visitors without an account; this creates their customer account. An email that already has an account is asked to sign in instead.</td></tr><tr><td>Company / shop name</td><td>Required</td></tr><tr><td>Trade licence / BIN / VAT number</td><td>Optional</td></tr><tr><td>Phone</td><td>Required; also used for text messages</td></tr><tr><td>Business type</td><td>Retailer, distributor, online seller, restaurant or hotel, company, institution, other</td></tr><tr><td>Business address</td><td></td></tr><tr><td>Tell us about your business</td><td>What they sell, roughly how much they would order</td></tr><tr><td>Terms</td><td>Shown only when you write terms in Settings; the applicant must tick the box</td></tr></tbody></table><p>A signed-in visitor sees which account they are applying with (name and email, with <strong>Not you? Sign out</strong>). When the form is sent, you receive an email (to the address in Settings, or the shop&#39;s &quot;new order&quot; address), and the applicant sees that their application is waiting.</p><div class="tip custom-block"><p class="custom-block-title">Spam protection</p><p>Tick the wholesale application and login forms under <strong>Settings → Integrations → Cloudflare Turnstile → Show on</strong> to protect them with Turnstile (free, in the core).</p></div><h3 id="approving-and-rejecting" tabindex="-1">Approving and rejecting <a class="header-anchor" href="#approving-and-rejecting" aria-label="Permalink to &quot;Approving and rejecting&quot;">​</a></h3><p>Applications arrive in <strong>Wholesale → Customers</strong>.</p><p><img src="'+n+'" alt="The wholesale customer list"></p><p><em>Filter by status, search by name, email, company or phone, and act on several at once.</em></p><p>Open one with <strong>Review</strong>. In the <strong>Decision</strong> box on the right:</p><ul><li><strong>Approve and email the customer</strong> — pick the level first (the default level is preselected). The account gets wholesale prices at that level, and the customer is emailed.</li><li><strong>Reject</strong> emails them too. Write a reason in the box and it goes in the email.</li><li>An approved account can be <strong>revoked</strong> the same way; it goes back to retail prices.</li><li><strong>Remove wholesale account</strong> deletes the wholesale account. The customer account itself stays.</li></ul><p><strong>Bulk actions</strong> on the list approve, reject, move to a level, or remove several accounts at once.</p><p>To approve everyone automatically, tick <strong>Approve applications automatically</strong> in <a href="/falconcms/wholesale/settings.html">Settings</a>. You can also give an existing customer a wholesale account, or change it, from their user screen (<strong>Users → edit → Wholesale</strong>).</p><h3 id="the-wholesale-customer-role" tabindex="-1">The Wholesale Customer role <a class="header-anchor" href="#the-wholesale-customer-role" aria-label="Permalink to &quot;The Wholesale Customer role&quot;">​</a></h3><p>Everyone who buys at wholesale prices carries the <strong>Wholesale Customer</strong> role, as an extra role beside their own. A customer stays a customer and staff stay staff, so the role gives nothing in the admin. It is given with approval and taken away when the account is rejected, revoked or removed. Find these customers under <strong>Users → Wholesale Customer</strong>; a &quot;Wholesale&quot; badge marks them.</p><hr><h2 id="the-customer-screen" tabindex="-1">The customer screen <a class="header-anchor" href="#the-customer-screen" aria-label="Permalink to &quot;The customer screen&quot;">​</a></h2><p><img src="'+i+'" alt="A wholesale customer&#39;s screen"></p><p><em>One customer&#39;s account: their company details, level, sales rep, tax exemption and a private note.</em></p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Level</strong></td><td>Which level&#39;s prices and rules they get</td></tr><tr><td><strong>Company, Trade licence, Business type, Phone, Address</strong></td><td>From the application; you can correct them. The company and BIN go on invoices.</td></tr><tr><td><strong>Their message</strong></td><td>What they wrote when applying</td></tr><tr><td><strong>Sales rep</strong></td><td>The rep who looks after them (see <a href="#sales-reps">Sales reps</a>)</td></tr><tr><td><strong>Tax exempt</strong></td><td>No tax on their orders, with a certificate number and an end date (empty: no end). The order records the certificate number and the invoice shows it. With prices entered including tax, the tax line goes but prices stay the same.</td></tr><tr><td><strong>Private note</strong></td><td>Only staff see it</td></tr></tbody></table><p>Further down the same screen:</p><ul><li><strong>Credit account (buy now, pay later)</strong> — whether they may buy on account, their credit limit and days to pay, what they owe and have available, their ledger, and forms to record a payment or an adjustment. See <a href="/falconcms/wholesale/ordering.html#buying-on-account-credit">Buying on account</a>.</li><li><strong>Contract prices</strong> — prices for this company only. See <a href="/falconcms/wholesale/pricing.html#contract-prices">Contract prices</a>.</li><li><strong>Team</strong> — the people who buy for this company, their role, and whether they have joined.</li><li><strong>Send an SMS</strong> — text the customer by hand, with ready-made messages to pick from (once SMS is set up in Settings).</li></ul><hr><h2 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h2><p>Levels are the kinds of trade customer you have: <em>Wholesale</em>, <em>Dealer</em>, <em>Distributor</em>. Each customer belongs to one. <strong>Wholesale → Levels</strong> lists them; one is the <strong>default</strong>, given to newly approved customers.</p><p><img src="'+l+'" alt="Editing a wholesale level"></p><p><em>A level: its discount, minimum order, the payment and shipping methods it may use, and spend discounts.</em></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Shown to the customer (&quot;Wholesale price · Dealer&quot;)</td></tr><tr><td><strong>Discount off retail (%)</strong></td><td>For products with no wholesale price of their own and no discounted category. 0 means only the products you price yourself get a wholesale price.</td></tr><tr><td><strong>Minimum order value</strong></td><td>Checkout refuses a smaller order. Whether retail-priced extras count is a setting (see <a href="/falconcms/wholesale/settings.html">Settings</a>).</td></tr><tr><td><strong>Minimum items per order</strong></td><td>The same, counted in items</td></tr><tr><td><strong>Payment methods</strong></td><td>Untick the methods this level may not use (Cash on Delivery, say). A method switched on later is offered until you untick it here. Unticking every method hides none.</td></tr><tr><td><strong>Shipping methods</strong></td><td>The same for shipping</td></tr><tr><td><strong>Free shipping from</strong></td><td>An order value from which shipping is free for this level; the cart tells the customer how much more gets it</td></tr><tr><td><strong>Spend discounts</strong></td><td>Up to three &quot;X% off orders of Y or more&quot;. The biggest one reached comes off the whole order as <em>Volume discount</em>, on top of wholesale prices, even with promotions off for wholesale.</td></tr><tr><td><strong>Deposit (%)</strong></td><td>&quot;Pay a 30% deposit now, the rest later&quot; at checkout, and whether it is the only way to pay. See <a href="/falconcms/wholesale/ordering.html#deposits">Deposits</a>.</td></tr></tbody></table><p>Moving a customer to another level changes their prices from their next page view.</p><hr><h2 id="company-accounts" tabindex="-1">Company accounts <a class="header-anchor" href="#company-accounts" aria-label="Permalink to &quot;Company accounts&quot;">​</a></h2><p>A business often has several people who order. The <strong>account owner</strong> (the person who applied) and any <strong>managers</strong> invite them from <strong>portal → Team</strong>, by email.</p><ul><li>The invitee gets a link, signs in or creates an account, and joins the company.</li><li>Everyone in the company buys at the <strong>company&#39;s</strong> level, prices and contract prices, uses its <strong>credit</strong>, and sees its <strong>shared order history, invoices and saved lists</strong>.</li><li><strong>Buyers</strong> order. <strong>Managers</strong> also invite and remove people and edit the company details.</li><li>The owner&#39;s saved delivery addresses are offered to everyone in the company at checkout.</li></ul><h3 id="order-approval-for-buyers" tabindex="-1">Order approval for buyers <a class="header-anchor" href="#order-approval-for-buyers" aria-label="Permalink to &quot;Order approval for buyers&quot;">​</a></h3><p>For each buyer the owner or a manager can require approval: <strong>every order</strong>, or orders <strong>above an amount</strong>. Such an order is placed <strong>on hold</strong> with offline payment (nothing is charged), the owner and managers are emailed, and they <strong>Approve</strong> it (it goes on as a normal order) or <strong>Decline</strong> it with a reason (it is cancelled, and stock and credit go back) in <strong>portal → Approvals</strong>. The buyer is emailed the decision, and their order list says <em>Awaiting approval</em> meanwhile.</p><hr><h2 id="sales-reps" tabindex="-1">Sales reps <a class="header-anchor" href="#sales-reps" aria-label="Permalink to &quot;Sales reps&quot;">​</a></h2><p>People on your staff who look after wholesale customers. Add them in <strong>Wholesale → Settings → Sales reps</strong>: a user&#39;s email and a commission percentage. Then give each customer a rep on their screen.</p><p>From then on every order of that customer records the rep and the commission (on the goods, after discounts), the rep is emailed about the order, and <strong>Wholesale → Reports</strong> totals orders, revenue and commission per rep. Adding someone who is already a rep changes their commission.</p>',46)])])}const f=t(h,[["render",d]]);export{w as __pageData,f as default};
